/* Only the exit button supplements a missing touch click; gameplay pointer ownership is unchanged. */
(()=>{
 const button=document.getElementById('exitGame');
 const contacts=new Set(),receipts=new Map();
 let gesture=null,pending=null;
 const inside=e=>{const r=button.getBoundingClientRect();return e.clientX>=r.left&&e.clientX<=r.right&&e.clientY>=r.top&&e.clientY<=r.bottom};
 const active=()=>started&&player&&!gameOverPending&&!window.gameExitDialogOpen&&menu.classList.contains('hidden')&&!document.hidden&&!button.classList.contains('hidden')&&!document.querySelector('dialog[open]');
 function requestExitConfirmation(){
  if(!active())return;
  showGameExitDialog(()=>{gameStormBoss.reset();gameStormCombat.cleanup();gameMachineCombat.cleanup();gameMachineBoss.reset();gameMachineFortress.reset();gameStormSky.reset();gameVolcanoBoss.reset();gameVolcanoCombat.cleanup();gameVolcano.reset();gameSnowfieldBoss.reset();gameScoring.finish('abandoned');itemMonsters.reset();started=false;window.gameAudioStarted=false;gameAudio.pause();player=null;boss=null;bullets=[];enemyBullets=[];warnings=[];enemies=[];particles=[];items=[];drag=null;keys.left=keys.right=keys.fire=false;menu.classList.remove('hidden');document.getElementById('exitGame').classList.add('hidden');drawChoices()});
 }
 function cancelPending(){
  if(gesture)gesture.valid=false;
  if(pending){clearTimeout(pending.timer);pending.valid=false;pending=null;}
 }
 function remember(e,valid){
  const receipt={id:e.pointerId,x:e.clientX,y:e.clientY,time:performance.now(),valid,handled:false,player};
  receipts.set(e.pointerId,receipt);
  for(const [id,r] of receipts)if(performance.now()-r.time>1500||receipts.size>8)receipts.delete(id);
  return receipt;
 }
 window.addEventListener('pointerdown',e=>{
  cancelPending();
  if(e.pointerType==='touch'){contacts.add(e.pointerId);receipts.delete(e.pointerId);if(contacts.size>1&&gesture)gesture.valid=false;}
 },true);
 window.addEventListener('pointerup',e=>contacts.delete(e.pointerId),true);
 window.addEventListener('pointercancel',e=>{contacts.delete(e.pointerId);cancelPending();},true);
 button.addEventListener('pointerdown',e=>{
  if(e.pointerType!=='touch')return;
  gesture={id:e.pointerId,x:e.clientX,y:e.clientY,time:performance.now(),player,valid:active()&&e.isPrimary&&contacts.size===1&&inside(e)};
 });
 button.addEventListener('pointermove',e=>{
  if(gesture&&gesture.id===e.pointerId&&(!inside(e)||Math.hypot(e.clientX-gesture.x,e.clientY-gesture.y)>12))gesture.valid=false;
 });
 button.addEventListener('pointercancel',e=>{if(e.pointerType==='touch'){remember(e,false);gesture=null;}});
 button.addEventListener('lostpointercapture',e=>{if(gesture&&gesture.id===e.pointerId)gesture.valid=false;});
 button.addEventListener('pointerup',e=>{
  if(e.pointerType!=='touch')return;
  const g=gesture;gesture=null;
  const valid=g&&g.id===e.pointerId&&g.valid&&g.player===player&&contacts.size===0&&performance.now()-g.time<=750&&inside(e)&&Math.hypot(e.clientX-g.x,e.clientY-g.y)<=12&&active();
  const receipt=remember(e,!!valid);
  if(!valid)return;
  // Give the browser's normal click priority; never dispatch a synthetic global click.
  pending=receipt;
  receipt.timer=setTimeout(()=>{
   if(pending!==receipt)return;pending=null;
   if(!receipt.valid||receipt.handled||receipt.player!==player||!active())return;
   receipt.handled=true;button.focus({preventScroll:true});requestExitConfirmation();
  },100);
 });
 button.addEventListener('click',e=>{
  // Keyboard, assistive technology, programmatic click and genuine mouse keep their original path.
  const touch=e.pointerType==='touch'||e.sourceCapabilities?.firesTouchEvents;
  const receipt=touch&&(receipts.get(e.pointerId)||[...receipts.values()].reverse().find(r=>performance.now()-r.time<1500&&Math.hypot(e.clientX-r.x,e.clientY-r.y)<=3));
  if(receipt){
   if(pending===receipt){clearTimeout(receipt.timer);pending=null;}
   if(!receipt.valid||receipt.handled||receipt.player!==player)return;
   receipt.handled=true;
  }
  requestExitConfirmation();
 });
 for(const name of ['blur','resize','orientationchange','keydown'])window.addEventListener(name,cancelPending);
 window.addEventListener('blur',()=>contacts.clear());
 for(const name of ['gameover','gameoverclose'])document.addEventListener(name,cancelPending);
 document.addEventListener('visibilitychange',()=>{if(document.hidden){contacts.clear();cancelPending();}});
 document.addEventListener('fullscreenchange',cancelPending);
 new MutationObserver(cancelPending).observe(menu,{attributes:true,attributeFilter:['class']});
 document.addEventListener('DOMContentLoaded',()=>{
  const dialog=document.getElementById('gameExitDialog');
  if(dialog)new MutationObserver(cancelPending).observe(dialog,{attributes:true,attributeFilter:['open']});
 },{once:true});
})();
